   286  /**
   287   * Given a cell, find the next cell in the sequence of all cells
   288   * to check in the iteration.
   289   */
   290  static H3Index nextCell(H3Index cell) {
   291      int res = H3_GET_RESOLUTION(cell);
   292      while (true) {
   293          // If this is a base cell, set to next base cell (or H3_NULL if done)
   294          if (res == 0) {
   295              return baseCellNumToCell(H3_GET_BASE_CELL(cell) + 1);
   296          }
   297
   298          // Faster cellToParent when we know the resolution is valid
   299          // and we're only moving up one level
   300          H3Index parent = cell;
   301          H3_SET_RESOLUTION(parent, res - 1);
   302          H3_SET_INDEX_DIGIT(parent, res, H3_DIGIT_MASK);
   303
   304          // If not the last sibling of parent, return next sibling
   305          Direction digit = H3_GET_INDEX_DIGIT(cell, res);
   306          if (digit < INVALID_DIGIT - 1) {
   307              H3_SET_INDEX_DIGIT(cell, res,
   308                                 digit + ((H3_EXPORT(isPentagon)(parent) &&
   309                                           digit == CENTER_DIGIT)
   310                                              ? 2  // Skip missing pentagon child
   311                                              : 1));
   312              return cell;
   313          }
   314          // Move up to the parent for the next loop iteration
   315          res--;
   316          cell = parent;
   317      }
   318  }
