   392  /**
   393   * Increment the polyfill iterator, running the polygon to cells algorithm.
   394   *
   395   * Briefly, the algorithm checks every cell in the global grid hierarchically,
   396   * starting with the base cells. Cells coarser than the target resolution are
   397   * checked for complete child inclusion using a bounding box guaranteed to
   398   * contain all children.
   399   * - If the bounding box is contained by the polygon, output is set to the cell
   400   * - If the bounding box intersects, recurse into the first child
   401   * - Otherwise, continue with the next cell in sequence
   402   *
   403   * For cells at the target resolution, a finer-grained check is used according
   404   * to the inclusion criteria set in flags.
   405   *
   406   * @param  iter Iterator to increment
   407   */
   408  void iterStepPolygonCompact(IterCellsPolygonCompact *iter) {
   409      H3Index cell = iter->cell;
   410
   411      // once the cell is H3_NULL, the iterator returns an infinite sequence of
   412      // H3_NULL
   413      if (cell == H3_NULL) return;
   414
   415      // For the first step, we need to evaluate the current cell; after that, we
   416      // should start with the next cell.
   417      if (iter->_started) {
   418          cell = nextCell(cell);
   419      } else {
   420          iter->_started = true;
   421      }
   422
   423      // Short-circuit iteration for 0-vert polygon
   424      if (iter->_polygon->geoloop.numVerts == 0) {
   425          iterDestroyPolygonCompact(iter);
   426          return;
   427      }
   428
   429      ContainmentMode mode = FLAG_GET_CONTAINMENT_MODE(iter->_flags);
   430
   431      while (cell) {
   432          int cellRes = H3_GET_RESOLUTION(cell);
   433
   434          // Target res: Do a fine-grained check
   435          if (cellRes == iter->_res) {
   436              if (mode == CONTAINMENT_CENTER || mode == CONTAINMENT_OVERLAPPING ||
   437                  mode == CONTAINMENT_OVERLAPPING_BBOX) {
   438                  // Check if the cell center is inside the polygon
   439                  LatLng center;
   440                  H3Error centerErr = H3_EXPORT(cellToLatLng)(cell, &center);
   441                  if (centerErr != E_SUCCESS) {
   442                      iterErrorPolygonCompact(iter, centerErr);
   443                      return;
   444                  }
   445                  if (pointInsidePolygon(iter->_polygon, iter->_bboxes,
   446                                         &center)) {
   447                      // Set to next output
   448                      iter->cell = cell;
   449                      return;
   450                  }
   451              }
   452              if (mode == CONTAINMENT_OVERLAPPING ||
   453                  mode == CONTAINMENT_OVERLAPPING_BBOX) {
   454                  // For overlapping, we need to do a quick check to determine
   455                  // whether the polygon is wholly contained by the cell. We
   456                  // check the first polygon vertex, which if it is contained
   457                  // could also mean we simply intersect.
   458
   459                  // Deferencing verts[0] is safe because we check numVerts above
   460                  LatLng firstVertex = iter->_polygon->geoloop.verts[0];
   461
   462                  // We have to check whether the point is in the expected range
   463                  // first, because out-of-bounds values will yield false
   464                  // positives with latLngToCell
   465                  if (bboxContains(&VALID_RANGE_BBOX, &firstVertex)) {
   466                      H3Index polygonCell;
   467                      H3Error polygonCellErr = H3_EXPORT(latLngToCell)(
   468                          &(iter->_polygon->geoloop.verts[0]), cellRes,
   469                          &polygonCell);
   470                      if (NEVER(polygonCellErr != E_SUCCESS)) {
   471                          // This should be unreachable with the bbox check
   472                          iterErrorPolygonCompact(iter, polygonCellErr);
   473                          return;
   474                      }
   475                      if (polygonCell == cell) {
   476                          // Set to next output
   477                          iter->cell = cell;
   478                          return;
   479                      }
   480                  }
   481              }
   482              if (mode == CONTAINMENT_FULL || mode == CONTAINMENT_OVERLAPPING ||
   483                  mode == CONTAINMENT_OVERLAPPING_BBOX) {
   484                  CellBoundary boundary;
   485                  H3Error boundaryErr =
   486                      H3_EXPORT(cellToBoundary)(cell, &boundary);
   487                  if (boundaryErr != E_SUCCESS) {
   488                      iterErrorPolygonCompact(iter, boundaryErr);
   489                      return;
   490                  }
   491                  BBox bbox;
   492                  H3Error bboxErr = cellToBBox(cell, &bbox, false);
   493                  if (NEVER(bboxErr != E_SUCCESS)) {
   494                      // Should be unreachable - invalid cells would be caught in
   495                      // the previous boundaryErr
   496                      iterErrorPolygonCompact(iter, bboxErr);
   497                      return;
   498                  }
   499                  // Check if the cell is fully contained by the polygon
   500                  if ((mode == CONTAINMENT_FULL ||
   501                       mode == CONTAINMENT_OVERLAPPING_BBOX) &&
   502                      cellBoundaryInsidePolygon(iter->_polygon, iter->_bboxes,
   503                                                &boundary, &bbox)) {
   504                      // Set to next output
   505                      iter->cell = cell;
   506                      return;
   507                  }
   508                  // For overlap, we've already checked for center point inclusion
   509                  // above; if that failed, we only need to check for line
   510                  // intersection
   511                  else if (mode == CONTAINMENT_OVERLAPPING &&
   512                           cellBoundaryCrossesPolygon(
   513                               iter->_polygon, iter->_bboxes, &boundary, &bbox)) {
   514                      // Set to next output
   515                      iter->cell = cell;
   516                      return;
   517                  }
   518              }
   519              if (mode == CONTAINMENT_OVERLAPPING_BBOX) {
   520                  // Get a bounding box containing all the cell's children, so
   521                  // this can work for the max size calculation
   522                  BBox bbox;
   523                  H3Error bboxErr = cellToBBox(cell, &bbox, true);
   524                  if (bboxErr) {
   525                      iterErrorPolygonCompact(iter, bboxErr);
   526                      return;
   527                  }
   528                  if (bboxOverlapsBBox(&iter->_bboxes[0], &bbox)) {
   529                      CellBoundary bboxBoundary = bboxToCellBoundary(&bbox);
   530                      if (
   531                          // cell bbox contains the polygon
   532                          bboxContainsBBox(&bbox, &iter->_bboxes[0]) ||
   533                          // polygon contains cell bbox
   534                          pointInsidePolygon(iter->_polygon, iter->_bboxes,
   535                                             &bboxBoundary.verts[0]) ||
   536                          // polygon crosses cell bbox
   537                          cellBoundaryCrossesPolygon(iter->_polygon,
   538                                                     iter->_bboxes, &bboxBoundary,
   539                                                     &bbox)) {
   540                          iter->cell = cell;
   541                          return;
   542                      }
   543                  }
   544              }
   545          }
   546
   547          // Coarser cell: Check the bounding box
   548          if (cellRes < iter->_res) {
   549              // Get a bounding box for all of the cell's children
   550              BBox bbox;
   551              H3Error bboxErr = cellToBBox(cell, &bbox, true);
   552              if (bboxErr) {
   553                  iterErrorPolygonCompact(iter, bboxErr);
   554                  return;
   555              }
   556              if (bboxOverlapsBBox(&iter->_bboxes[0], &bbox)) {
   557                  // Quick check for possible containment
   558                  if (bboxContainsBBox(&iter->_bboxes[0], &bbox)) {
   559                      CellBoundary bboxBoundary = bboxToCellBoundary(&bbox);
   560                      // Do a fine-grained, more expensive check on the polygon
   561                      if (cellBoundaryInsidePolygon(iter->_polygon, iter->_bboxes,
   562                                                    &bboxBoundary, &bbox)) {
   563                          // Bounding box is fully contained, so all children are
   564                          // included. Set to next output.
   565                          iter->cell = cell;
   566                          return;
   567                      }
   568                  }
   569                  // Otherwise, the intersecting bbox means we need to test all
   570                  // children, starting with the first child
   571                  H3Index child;
   572                  H3Error childErr =
   573                      H3_EXPORT(cellToCenterChild)(cell, cellRes + 1, &child);
   574                  if (childErr) {
   575                      iterErrorPolygonCompact(iter, childErr);
   576                      return;
   577                  }
   578                  // Restart the loop with the child cell
   579                  cell = child;
   580                  continue;
   581              }
   582          }
   583
   584          // Find the next cell in the sequence of all cells and continue
   585          cell = nextCell(cell);
   586      }
   587      // If we make it out of the loop, we're done
   588      iterDestroyPolygonCompact(iter);
   589  }
