   592   * Destroy an iterator, releasing any allocated memory. Iterators destroyed in
   593   * this manner are safe to use but will always return H3_NULL.
   594   * @param  iter Iterator to destroy
   595   */
   596  void iterDestroyPolygonCompact(IterCellsPolygonCompact *iter) {
   597      if (iter->_bboxes) {
   598          H3_MEMORY(free)(iter->_bboxes);
   599      }
   600      iter->cell = H3_NULL;
   601      iter->error = E_SUCCESS;
   602      iter->_polygon = NULL;
   603      iter->_res = -1;
   604      iter->_flags = 0;
   605      iter->_bboxes = NULL;
   606  }
