   632      IterCellsPolygonCompact cellIter =
   633          iterInitPolygonCompact(polygon, res, flags);
   634      // Create the sub-iterator for children
   635      IterCellsChildren childIter = iterInitParent(cellIter.cell, res);
   636
   637      IterCellsPolygon iter = {.cell = childIter.h,
   638                               .error = cellIter.error,
   639                               ._cellIter = cellIter,
   640                               ._childIter = childIter};
