   675   * Destroy an iterator, releasing any allocated memory. Iterators destroyed in
   676   * this manner are safe to use but will always return H3_NULL.
   677   * @param  iter Iterator to destroy
   678   */
   679  void iterDestroyPolygon(IterCellsPolygon *iter) {
   680      iterDestroyPolygonCompact(&(iter->_cellIter));
   681      // null out the child iterator by passing H3_NULL
   682      _iterInitParent(H3_NULL, 0, &(iter->_childIter));
   683      iter->cell = H3_NULL;
   684      iter->error = E_SUCCESS;
   685  }
