   180  bool cellBoundaryCrossesGeoLoop(const GeoLoop *geoloop, const BBox *loopBBox,
   181                                  const CellBoundary *boundary,
   182                                  const BBox *boundaryBBox) {
   183      if (!bboxOverlapsBBox(loopBBox, boundaryBBox)) {
   184          return false;
   185      }
   186      LongitudeNormalization loopNormalization;
   187      LongitudeNormalization boundaryNormalization;
   188      bboxNormalization(loopBBox, boundaryBBox, &loopNormalization,
   189                        &boundaryNormalization);
   190
   191      CellBoundary normalBoundary = *boundary;
   192      for (int i = 0; i < boundary->numVerts; i++) {
   193          normalBoundary.verts[i].lng =
   194              normalizeLng(normalBoundary.verts[i].lng, boundaryNormalization);
   195      }
   196
   197      BBox normalBoundaryBBox = {
   198          .north = boundaryBBox->north,
   199          .south = boundaryBBox->south,
   200          .east = normalizeLng(boundaryBBox->east, boundaryNormalization),
   201          .west = normalizeLng(boundaryBBox->west, boundaryNormalization)};
   202
   203      LatLng loop1;
   204      LatLng loop2;
   205      for (int i = 0; i < geoloop->numVerts; i++) {
   206          loop1 = geoloop->verts[i];
   207          loop1.lng = normalizeLng(loop1.lng, loopNormalization);
   208          loop2 = geoloop->verts[(i + 1) % geoloop->numVerts];
   209          loop2.lng = normalizeLng(loop2.lng, loopNormalization);
   210
   211          // Quick check if the line segment overlaps our bbox
   212          if ((loop1.lat >= normalBoundaryBBox.north &&
   213               loop2.lat >= normalBoundaryBBox.north) ||
   214              (loop1.lat <= normalBoundaryBBox.south &&
   215               loop2.lat <= normalBoundaryBBox.south) ||
   216              (loop1.lng <= normalBoundaryBBox.west &&
   217               loop2.lng <= normalBoundaryBBox.west) ||
   218              (loop1.lng >= normalBoundaryBBox.east &&
   219               loop2.lng >= normalBoundaryBBox.east)) {
   220              continue;
   221          }
